WHERE ppl.is_active >= 0

    AND cus.id = #{filter.organizationId}


    AND ppl.is_active = #{filter.status}


    AND ppl.ppl_code LIKE CONCAT("%", #{filter.searchText}, "%")


    AND ppl.created_by = #{userId}

mapper.select:
SELECT



 ORDER BY


        ${filter.orderBy}


        ppl.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(products.id)
FROM products
         INNER JOIN product_pgroups ON products.id = product_pgroups.product_id
         INNER JOIN product_prices ON products.id = product_prices.product_id
WHERE products.is_active = 1
  AND products.company_id = #{filter.companyId}
  AND product_pgroups.pgroup_id = #{filter.productGroupId}
  AND product_prices.price_type_id = #{filter.priceTypeId}
  AND product_prices.uom_id = products.price_uom_id

