UPDATE product_price_lists SET
   is_active = -1,
   modified =   NOW(),
   modified_by = #{userId}
WHERE id = #{id};

UPDATE product_price_lists SET
    is_active = #{productListApproveStatus.status}
WHERE id = #{productListApproveStatus.id};
